class Solution { public int minTrioDegree(int n,int[][] edges){int[] degree=new int[n];boolean[][] connected=new boolean[n][n];for(int[] edge:edges){int a=edge[0]-1,b=edge[1]-1;degree[a]++;degree[b]++;connected[a][b]=connected[b][a]=true;}int answer=Integer.MAX_VALUE;for(int first=0;first<n;first++)for(int second=first+1;second<n;second++)if(connected[first][second])for(int third=second+1;third<n;third++)if(connected[first][third]&&connected[second][third])answer=Math.min(answer,degree[first]+degree[second]+degree[third]-6);return answer==Integer.MAX_VALUE?-1:answer;} }
